css:
  :root {
    --bg: #f3f3ef;
    --surface: #ffffff;
    --surface-2: #fafaf7;
    --line: #e5e5df;
    --line-strong: #d4d5ce;
    --ink: #1a1c1f;
    --ink-2: #545b65;
    --ink-3: #646b76;
    --focus: #2563eb;
    --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
  }

  *, *::before, *::after { box-sizing: border-box; }
  html { -webkit-text-size-adjust: 100%; }

  body {
    margin: 0;
    min-height: 100vh;
    background: var(--bg);
    color: var(--ink);
    font-family: var(--font);
    font-size: 14px;
    line-height: 1.45;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }

  [hidden] { display: none !important; }
  button, input, select { font: inherit; color: inherit; }
  button { cursor: pointer; }
  svg { display: block; }

  .sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  :focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }

  .shell {
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 32px;
  }

  .topbar {
    background: var(--surface);
    border-bottom: 1px solid var(--line);
  }

  .topbar-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    height: 56px;
  }

  .brand {
    font-size: 13px;
    font-weight: 600;
    letter-spacing: -0.01em;
  }

  .crumbs {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 12.5px;
    color: var(--ink-3);
  }

  .crumbs svg { color: #9a9fa7; }
  .crumbs .current { color: var(--ink-2); font-weight: 500; }

  main.shell {
    padding-top: 28px;
    padding-bottom: 56px;
  }

  .page-head { margin-bottom: 18px; }

  .eyebrow {
    margin: 0 0 6px;
    color: var(--ink-3);
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
  }

  h1 {
    margin: 0;
    font-size: 28px;
    font-weight: 600;
    line-height: 1.1;
    letter-spacing: -0.03em;
  }

  .sub {
    margin: 7px 0 0;
    max-width: 62ch;
    color: var(--ink-2);
    font-size: 13px;
  }

  .panel {
    background: var(--surface);
    border: 1px solid var(--line);
    border-radius: 10px;
    box-shadow: 0 1px 2px rgba(20, 23, 26, 0.04), 0 20px 44px -36px rgba(20, 23, 26, 0.28);
    overflow: hidden;
  }

  .toolbar {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 14px 16px;
    border-bottom: 1px solid var(--line);
  }

  .search-field {
    position: relative;
    flex: 1 1 auto;
    max-width: 380px;
    min-width: 0;
  }

  .search-icon {
    position: absolute;
    left: 11px;
    top: 50%;
    transform: translateY(-50%);
    color: #737a85;
    pointer-events: none;
  }

  .search-field input {
    width: 100%;
    height: 38px;
    padding: 0 38px 0 33px;
    border: 1px solid var(--line-strong);
    border-radius: 7px;
    background: var(--surface);
    color: var(--ink);
    font-size: 13px;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
  }

  .search-field input::placeholder { color: #6b7280; }
  .search-field input:hover { border-color: #c3c4bd; }

  .search-field input:focus {
    outline: none;
    border-color: var(--focus);
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.12);
  }

  .keyhint {
    position: absolute;
    right: 9px;
    top: 50%;
    transform: translateY(-50%);
    padding: 2px 5px;
    border: 1px solid var(--line);
    border-bottom-color: var(--line-strong);
    border-radius: 4px;
    background: var(--surface-2);
    color: var(--ink-3);
    font-family: var(--mono);
    font-size: 10px;
    line-height: 1;
    pointer-events: none;
  }

  .select-field {
    position: relative;
    flex: 0 0 auto;
  }

  .select-field select {
    height: 38px;
    padding: 0 32px 0 12px;
    appearance: none;
    -webkit-appearance: none;
    border: 1px solid var(--line-strong);
    border-radius: 7px;
    background: var(--surface);
    color: var(--ink-2);
    font-size: 13px;
    font-weight: 500;
    cursor: pointer;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
  }

  .select-field select:hover { border-color: #c3c4bd; }

  .select-field select:focus {
    outline: none;
    border-color: var(--focus);
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.12);
  }

  .select-icon {
    position: absolute;
    right: 10px;
    top: 50%;
    transform: translateY(-50%);
    color: #737a85;
    pointer-events: none;
  }

  .export-btn {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    height: 38px;
    margin-left: auto;
    padding: 0 14px;
    border: 1px solid #191b1e;
    border-radius: 7px;
    background: #1b1d21;
    color: #ffffff;
    font-size: 12.5px;
    font-weight: 600;
    letter-spacing: 0.01em;
    white-space: nowrap;
    transition: background 0.15s ease, border-color 0.15s ease, transform 0.05s ease;
  }

  .export-btn svg { color: #cfd2d7; }
  .export-btn:hover { background: #000000; border-color: #000000; }
  .export-btn:active { transform: translateY(1px); }

  .table-wrap { width: 100%; }

  table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }

  thead th {
    height: 36px;
    padding: 0;
    border-bottom: 1px solid var(--line);
    background: var(--surface-2);
    color: #5e6570;
    font-size: 11.5px;
    font-weight: 600;
    letter-spacing: 0.01em;
    text-align: left;
  }

  .sort-btn {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    width: 100%;
    height: 36px;
    padding: 0 clamp(12px, 1.7vw, 20px);
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    letter-spacing: inherit;
    text-align: inherit;
  }

  .sort-btn:hover { color: var(--ink); }
  .text-right .sort-btn { justify-content: flex-end; }

  .sort-icon {
    flex: none;
    color: currentColor;
    opacity: 0;
    transition: opacity 0.12s ease, transform 0.12s ease;
  }

  .sort-btn:hover .sort-icon { opacity: 0.45; }
  th[aria-sort="ascending"] .sort-icon,
  th[aria-sort="descending"] .sort-icon { opacity: 0.9; }
  th[aria-sort="ascending"] .sort-icon { transform: rotate(180deg); }

  tbody td {
    height: 54px;
    padding: 0 clamp(12px, 1.7vw, 20px);
    font-size: 13px;
    vertical-align: middle;
  }

  tbody tr + tr td { border-top: 1px solid var(--line); }
  tbody tr[data-order]:hover { background: var(--surface-2); }

  .cell-order {
    color: #24272c;
    font-family: var(--mono);
    font-size: 12.5px;
    font-weight: 500;
    letter-spacing: -0.01em;
    white-space: nowrap;
  }

  .customer-name {
    display: block;
    color: var(--ink);
    font-size: 13px;
    font-weight: 500;
    line-height: 1.35;
  }

  .customer-email {
    display: block;
    margin-top: 1px;
    overflow: hidden;
    color: var(--ink-3);
    font-size: 11.5px;
    line-height: 1.35;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .cell-status { white-space: nowrap; }

  .chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 22px;
    padding: 0 8px;
    border: 1px solid transparent;
    border-radius: 5px;
    font-size: 11.5px;
    font-weight: 600;
    line-height: 1;
    white-space: nowrap;
  }

  .chip-dot {
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: currentColor;
  }

  .chip-paid {
    border-color: #d2e6da;
    background: #e8f3ec;
    color: #14613e;
  }

  .chip-pending {
    border-color: #ecdcb8;
    background: #faf0d8;
    color: #6d4900;
  }

  .chip-refunded {
    border-color: #dadeee;
    background: #eef0fa;
    color: #3e4a88;
  }

  .cell-amount {
    color: var(--ink);
    font-variant-numeric: tabular-nums;
    font-weight: 500;
    letter-spacing: -0.005em;
    text-align: right;
    white-space: nowrap;
  }

  .currency {
    margin-right: 1px;
    color: var(--ink-3);
    font-weight: 500;
  }

  .cell-created {
    color: var(--ink-2);
    font-variant-numeric: tabular-nums;
    text-align: right;
    white-space: nowrap;
  }

  .table-empty {
    margin: 0;
    padding: 28px 16px;
    background: var(--surface-2);
    color: var(--ink-2);
    font-size: 12.5px;
    text-align: center;
  }

  .pager {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 12px 20px;
    border-top: 1px solid var(--line);
  }

  .pager-count {
    margin: 0;
    color: var(--ink-3);
    font-size: 12px;
    font-variant-numeric: tabular-nums;
  }

  .pager-controls { display: flex; align-items: center; gap: 6px; }

  .icon-btn {
    display: grid;
    place-items: center;
    width: 32px;
    height: 32px;
    padding: 0;
    border: 1px solid var(--line-strong);
    border-radius: 6px;
    background: var(--surface);
    color: var(--ink-2);
    transition: background 0.15s ease, border-color 0.15s ease;
  }

  .icon-btn:hover:not(:disabled) { background: var(--surface-2); border-color: #c3c4bd; }
  .icon-btn:disabled { opacity: 0.4; cursor: not-allowed; }

  .page-current {
    display: grid;
    place-items: center;
    min-width: 32px;
    height: 32px;
    padding: 0 8px;
    border: 1px solid #c9cac3;
    border-radius: 6px;
    background: #f5f5f1;
    color: var(--ink);
    font-size: 12px;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
  }

  .empty-section { margin-top: 32px; }

  .empty-label {
    display: flex;
    align-items: center;
    gap: 12px;
    margin: 0 0 10px;
    color: var(--ink-2);
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.01em;
  }

  .empty-label::after {
    content: "";
    flex: 1;
    height: 1px;
    background: var(--line);
  }

  .empty-panel {
    padding: 32px 24px 30px;
    border: 1px dashed #d2d4cc;
    border-radius: 10px;
    background: #fbfbf9;
    text-align: center;
  }

  .empty-icon {
    display: grid;
    place-items: center;
    width: 40px;
    height: 40px;
    margin: 0 auto 12px;
    border: 1px solid var(--line);
    border-radius: 50%;
    background: linear-gradient(180deg, #ffffff, #f1f1ec);
    box-shadow: inset 0 1px 0 #ffffff;
    color: #646b74;
  }

  .empty-panel h3 {
    margin: 0;
    font-size: 13.5px;
    font-weight: 600;
    letter-spacing: -0.01em;
  }

  .empty-panel p {
    max-width: 44ch;
    margin: 5px auto 14px;
    color: var(--ink-2);
    font-size: 12.5px;
    line-height: 1.5;
  }

  .clear-btn {
    height: 34px;
    padding: 0 14px;
    border: 1px solid var(--line-strong);
    border-radius: 6px;
    background: var(--surface);
    color: var(--ink-2);
    font-size: 12px;
    font-weight: 600;
    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
  }

  .clear-btn:hover { border-color: #c3c4bd; background: #f7f7f3; color: var(--ink); }

  @media (max-width: 720px) {
    .shell { padding: 0 16px; }
    .topbar-inner { height: 52px; }
    .crumbs { display: none; }

    main.shell {
      padding-top: 20px;
      padding-bottom: 40px;
    }

    .page-head { margin-bottom: 16px; }
    h1 { font-size: 25px; }
    .sub { font-size: 12.5px; }

    .toolbar {
      flex-wrap: wrap;
      gap: 8px;
      padding: 12px;
    }

    .search-field { flex-basis: 100%; max-width: none; }
    .keyhint { display: none; }

    .search-field input,
    .select-field select {
      height: 42px;
      font-size: 16px;
    }

    .select-field { flex: 1 1 auto; min-width: 0; }
    .select-field select { width: 100%; }
    .export-btn { height: 42px; font-size: 13px; }

    thead { display: none; }
    table, tbody { display: block; }

    tbody tr[data-order] {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 2px 12px;
      padding: 12px 14px;
      border-top: 1px solid var(--line);
    }

    tbody tr[data-order]:first-child { border-top: 0; }
    tbody td { display: block; height: auto; padding: 0; border: 0; }

    .cell-order { grid-column: 1; align-self: center; }
    .cell-status { grid-column: 2; justify-self: end; align-self: center; }
    .cell-customer { grid-column: 1 / -1; min-width: 0; margin-top: 5px; }
    .customer-email { overflow-wrap: anywhere; white-space: normal; }

    .cell-amount {
      grid-column: 1;
      margin-top: 8px;
      font-size: 12.5px;
      text-align: left;
    }

    .cell-created {
      grid-column: 2;
      margin-top: 8px;
      font-size: 12.5px;
      text-align: right;
    }

    .cell-amount::before,
    .cell-created::before {
      margin-right: 5px;
      color: var(--ink-3);
      font-size: 11px;
      font-weight: 500;
    }

    .cell-amount::before { content: "Amount"; }
    .cell-created::before { content: "Created"; }

    .table-empty { padding: 26px 16px; }
    .pager { padding: 12px 14px; }
    .page-current, .icon-btn { width: 34px; height: 34px; }
    .empty-section { margin-top: 26px; }
    .empty-panel { padding: 28px 18px 26px; }
  }

  @media (prefers-reduced-motion: reduce) {
    * { transition-duration: 0.01ms !important; }
  }
